import { useEffect, useRef, useState } from "react";

const branches = ["Nava India", "RS Puram", "Kovaipudur"];

export default function AdminGallery() {
  const [images, setImages] = useState([]);
  const [branch, setBranch] = useState("Nava India");
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState("");
  const [error, setError] = useState("");

  const fileRef = useRef(null);

  const fetchImages = async () => {
    const res = await fetch("http://localhost:5001/admin/gallery");
    const data = await res.json();
    setImages(data);
  };

  useEffect(() => {
    fetchImages();
  }, []);

  const handleUpload = async () => {
    const file = fileRef.current.files[0];
    if (!file) return;

    setLoading(true);
    setError("");
    setSuccess("");

    const formData = new FormData();
    formData.append("image", file);
    formData.append("branch", branch);

    const res = await fetch("http://localhost:5001/admin/gallery", {
      method: "POST",
      body: formData,
    });

    const data = await res.json();

    if (res.ok) {
      setImages((prev) => [data, ...prev]);
      setSuccess("✅ Image uploaded successfully");
      setPreview(null);
      fileRef.current.value = "";
    } else {
      setError(data.error);
    }

    setLoading(false);
  };

  return (
    <div className="p-10 text-white">
      <h1 className="text-3xl font-bold text-yellow-400 mb-8">
        Gallery Manager
      </h1>

      <div className="bg-[#0d0d0d] p-6 rounded-2xl max-w-xl border border-yellow-500/30">
        <select
          value={branch}
          onChange={(e) => setBranch(e.target.value)}
          className="w-full mb-4 bg-black border border-yellow-500/40 p-2 rounded-xl"
        >
          {branches.map((b) => (
            <option key={b}>{b}</option>
          ))}
        </select>

        <input
          ref={fileRef}
          type="file"
          accept="image/*"
          onChange={(e) =>
            setPreview(URL.createObjectURL(e.target.files[0]))
          }
          className="file:bg-yellow-400 file:text-black file:px-5 file:py-2"
        />

        {preview && (
          <img
            src={preview}
            className="mt-4 w-40 h-40 object-cover rounded-xl"
          />
        )}

        <button
          onClick={handleUpload}
          disabled={loading}
          className="mt-4 bg-yellow-400 text-black px-6 py-2 rounded-xl"
        >
          {loading ? "Uploading..." : "Upload"}
        </button>

        {success && <p className="text-green-400 mt-3">{success}</p>}
        {error && <p className="text-red-400 mt-3">{error}</p>}
      </div>
    </div>
  );
}
